upserted as (
  insert into public.passport_matches (id, season, match_date, match_time, date_precision, status, competition, competition_code, competition_source_name, round, opponent, club_is_home, neutral_site, home_team, away_team, home_score, away_score, club_score, opponent_score, score_display, outcome, source_provider, source_match_id, source_url, source_confidence, date_confidence, score_confidence, venue_confidence, historical_source_no, officiality, dataset_origin, data_notes)
  select id, season, match_date, match_time, date_precision, status, competition, competition_code, competition_source_name, round, opponent, club_is_home, neutral_site, home_team, away_team, home_score, away_score, club_score, opponent_score, score_display, outcome, source_provider, source_match_id, source_url, source_confidence, date_confidence, score_confidence, venue_confidence, historical_source_no, officiality, dataset_origin, data_notes from payload
  on conflict (id) do update set
    season = excluded.season,
    match_date = excluded.match_date,
    match_time = excluded.match_time,
    date_precision = excluded.date_precision,
    status = excluded.status,
    competition = excluded.competition,
    competition_code = excluded.competition_code,
    competition_source_name = excluded.competition_source_name,
    round = excluded.round,
    opponent = excluded.opponent,
    club_is_home = excluded.club_is_home,
    neutral_site = excluded.neutral_site,
    home_team = excluded.home_team,
    away_team = excluded.away_team,
    home_score = excluded.home_score,
    away_score = excluded.away_score,
    club_score = excluded.club_score,
    opponent_score = excluded.opponent_score,
    score_display = excluded.score_display,
    outcome = excluded.outcome,
    source_provider = excluded.source_provider,
    source_match_id = excluded.source_match_id,
    source_url = excluded.source_url,
    source_confidence = excluded.source_confidence,
    date_confidence = excluded.date_confidence,
    score_confidence = excluded.score_confidence,
    venue_confidence = excluded.venue_confidence,
    historical_source_no = excluded.historical_source_no,
    officiality = excluded.officiality,
    dataset_origin = excluded.dataset_origin,
    data_notes = excluded.data_notes,
    updated_at = now()
  where (public.passport_matches.season, public.passport_matches.match_date, public.passport_matches.match_time, public.passport_matches.date_precision, public.passport_matches.status, public.passport_matches.competition, public.passport_matches.competition_code, public.passport_matches.competition_source_name, public.passport_matches.round, public.passport_matches.opponent, public.passport_matches.club_is_home, public.passport_matches.neutral_site, public.passport_matches.home_team, public.passport_matches.away_team, public.passport_matches.home_score, public.passport_matches.away_score, public.passport_matches.club_score, public.passport_matches.opponent_score, public.passport_matches.score_display, public.passport_matches.outcome, public.passport_matches.source_provider, public.passport_matches.source_match_id, public.passport_matches.source_url, public.passport_matches.source_confidence, public.passport_matches.date_confidence, public.passport_matches.score_confidence, public.passport_matches.venue_confidence, public.passport_matches.historical_source_no, public.passport_matches.officiality, public.passport_matches.dataset_origin, public.passport_matches.data_notes)
    is distinct from (excluded.season, excluded.match_date, excluded.match_time, excluded.date_precision, excluded.status, excluded.competition, excluded.competition_code, excluded.competition_source_name, excluded.round, excluded.opponent, excluded.club_is_home, excluded.neutral_site, excluded.home_team, excluded.away_team, excluded.home_score, excluded.away_score, excluded.club_score, excluded.opponent_score, excluded.score_display, excluded.outcome, excluded.source_provider, excluded.source_match_id, excluded.source_url, excluded.source_confidence, excluded.date_confidence, excluded.score_confidence, excluded.venue_confidence, excluded.historical_source_no, excluded.officiality, excluded.dataset_origin, excluded.data_notes)
  returning (xmax = 0) as inserted
)
insert into public.passport_sync_runs (
  provider, started_at, finished_at, status,
  inserted_count, updated_count, unchanged_count, failed_count, metadata
)
select
  'historical_csv_1943_2026',
  now(),
  now(),
  'success',
  count(*) filter (where inserted),
  count(*) filter (where not inserted),
  (select count(*) from payload) - count(*),
  0,
  jsonb_build_object(
    'source_file', 'passaporte_esmeraldino_1943_2026_FINAL.csv',
    'part', 13,
    'total_parts', '13',
    'record_count', (select count(*) from payload)
  )
from upserted
returning
  inserted_count as "inseridos",
  updated_count as "atualizados",
  unchanged_count as "sem_mudanca",
  failed_count as "erros";